"""Find end-to-end cause-effect chains in a FISH task set automatically (no hand-written path).

Graph: callbacks and stimulus sources of extract_fish_tasks.py's JSON; SOLID edges = the trigger edges inside tasks (identity-
paired), DOTTED edges = links between tasks: a polled read / held pointer / state candidate from the task that publishes the
topic (its publishing callback, found from that task's own edges) to the reading callback. tf lookups are not chain links.
A chain = a simple path from a start to an end; `--criterion latency` (default) picks the path with the largest
Σ(hop p50 + callback C p50) + Σ(polled age p50) — the critical cause-effect chain between the endpoints — `--criterion hops`
the one with most identity-paired hops. `--all` lists, per stimulus source, its longest chain inside its own task (the
"analyzable chain breakdown"). Output: a spec for scripts/chain_figure.py (vertex ids, auto labels, rows per task).
  python3 chain_find.py <fish_tasks.json> --from <node|entity substring> --to <substring> [-o spec.json] [--criterion latency|hops]
  python3 chain_find.py <fish_tasks.json> --all"""
import argparse, collections, json, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from task_viz import short_node, short_ent  # noqa: E402


def load(path):
    d = json.load(open(path)); V = {}; task_of = {}
    for t in d['tasks']:
        for v in t['vertices']: V[v['id']] = v; task_of[v['id']] = t['id']
        for s in t['sources']:
            if s.get('kind') != 'stimulus': continue
            topic = s['name'].split('→')[-1].strip()
            if s['vertex'] not in V:      # one publisher thread (e.g. the rosbag player) is one vertex that feeds several topics
                V[s['vertex']] = dict(id=s['vertex'], name=s['name'], names=[s['name']], node=s['name'].split(' / ')[0], entity=topic, topics=[topic], etype='thread',
                                      n=s.get('n_releases'), C=None, source=True, ia=(s.get('inter_arrival') or {}).get('p50'))
                task_of[s['vertex']] = t['id']
            else:
                V[s['vertex']]['names'].append(s['name']); V[s['vertex']]['topics'].append(topic)
    out = collections.defaultdict(list)
    for t in d['tasks']:
        for e in t['edges']:
            if e['u'] in V and e['v'] in V:
                out[e['u']].append(dict(v=e['v'], style='solid', kind=e['kind'], prov=e.get('prov') or '', hop=(e.get('delta') or {}).get('p50') or 0, n=e.get('n_pairs'), topic=e.get('topic')))
    # publisher vertex of a topic inside a task: the source side of that task's edges carrying the topic
    pub_in_task = collections.defaultdict(set)
    for t in d['tasks']:
        for e in t['edges']:
            if e.get('topic'): pub_in_task[(t['id'], e['topic'])].add(e['u'])
    n_dotted = 0
    for s in d['sampled']:
        if s.get('method') in ('tf_lookup', 'tf_static') or not s.get('topic') or s['reader_vertex'] not in V: continue
        for wt in (s.get('writer_tasks') or []):
            # the publishing callback of that topic in the writer task; a node-internal state read (method probe, held pointer) has
            # no topic in the writer task -> the record's own writer_vertex (fish_20261026_201712: the probe link vanished once it got a name)
            wv = s.get('writer_vertex')
            for u in (pub_in_task.get((wt, s['topic'])) or ({wv} if wv in V and task_of.get(wv) == wt else ())):
                if u != s['reader_vertex'] and task_of.get(u) != task_of.get(s['reader_vertex']):
                    out[u].append(dict(v=s['reader_vertex'], style='dotted', kind=str(s.get('method')), prov=s.get('prov') or '', hop=s.get('age_p50') or 0, n=s.get('n'), topic=s['topic'])); n_dotted += 1
    for c in d.get('candidates', []):
        if c['u'] in V and c['v'] in V:
            out[c['u']].append(dict(v=c['v'], style='dotted', kind=c.get('nature', 'candidate'), prov='no evidence record', hop=0, n=None, topic=c.get('topic'), cand=True)); n_dotted += 1
    return d, V, task_of, out, n_dotted


def label_of(v, topic=None):
    """up to 3 lines: the node's last path element (wrapped once at an underscore), then the entity"""
    if v.get('source'):
        tp = (topic or v['entity']).split('/')[-1]
        return f"{v['node'].split('/')[-1][:22]}\nthread → {tp[:20]}"
    node = (v.get('node') or '').rstrip('/').split('/')[-1]
    if len(node) > 22:
        cut = node.rfind('_', 0, 22); cut = cut if cut > 6 else 22
        node = node[:cut] + '\n' + node[cut:].lstrip('_')[:22]
    return f"{node}\n{short_ent(v.get('etype'), v.get('entity'), None, 24)}"


def best_path(V, out, starts, ends, criterion, allow_cand=False, max_hops=60, forbidden=()):
    """the path with the FEWEST links between tasks (a cause-effect chain crosses as few sampling boundaries as it must), then
    the largest criterion (Σ hop + C p50, or trigger hops). Candidates (no evidence) only with allow_cand."""
    best = (None, None); explored = [0]
    def score(path_edges):
        solid = sum(1 for e in path_edges if e['style'] == 'solid'); dotted = len(path_edges) - solid
        lat = sum((e['hop'] or 0) for e in path_edges) + sum(((V[e['v']].get('C') or {}).get('p50') or 0) for e in path_edges)
        return (-dotted, lat, solid) if criterion == 'latency' else (-dotted, solid, lat)
    sys.setrecursionlimit(10000)
    def dfs(u, path_v, path_e, dotted):
        nonlocal best
        explored[0] += 1
        if explored[0] > 3_000_000: return
        if best[0] is not None and -dotted < best[0][0]: return          # already more sampling boundaries than the best chain
        if u in ends and path_e:
            sc = score(path_e)
            if best[0] is None or sc > best[0]: best = (sc, (list(path_v), list(path_e)))
            return
        if len(path_e) >= max_hops: return
        for e in out.get(u, ()):
            if e['v'] in path_v or e['v'] in forbidden or (e.get('cand') and not allow_cand): continue
            path_v.append(e['v']); path_e.append(e); dfs(e['v'], path_v, path_e, dotted + (e['style'] != 'solid')); path_v.pop(); path_e.pop()
    for s in starts: dfs(s, [s], [], 0)
    return best, explored[0]


