    print(f"best chain ({a.criterion}{', via ' + ' > '.join(a.via) if a.via else ''}{', candidates allowed' if a.allow_candidates else ''}): {len(es)} links "
          f"({sum(1 for e in es if e['style'] == 'solid')} trigger hops, {sum(1 for e in es if e['style'] != 'solid')} between tasks, {sum(1 for e in es if e.get('cand'))} candidates), "
          f"Σ hop+C p50 {lat / 1e6:.1f} ms; {n_exp} DFS steps", file=sys.stderr)
